      "title": "",
      "text": "南京市委统战部、市委宣传部、市民宗局、市司法局联合下发《关于学习宣传贯彻<中华人民共和国民族团结进步促进法>的通知》，全面部署学习宣传贯彻工作，将法律纳入各级党委（党组）理论学习中心组学习内容等。",
