      "title": "",
      "text": "安徽省民宗委党组召开理论学习中心组学习（扩大）会议，专题宣讲民族团结进步促进法，与会人员围绕学习宣传贯彻法律开展交流研讨，8名同志作重点发言，随机抽点14名同志交流发言。",
