      "region": "广西",
      "region_group": "广东、广西、海南",
      "language": "中文",
      "attitude": "支持认可",
      "title": "",
      "text": "广西三江基层立法联系点收集200条意见建议7条被立法机关吸纳。其中广西柳州融水村民建议发展少数民族地区旅游业被采纳广西师范大学教授建议将各族群众统一改为各族人民也被采纳。村民蓝远克将村民心声写成建议上报表示大家的心声被听到了。",
      "topic": "",
      "likes": 0,
      "comments": 0,
